    def test_sign(
        self,
        name: str,
        seed: bytes,
        pk_expected: bytes,
        msg: bytes,
        ctx: bytes,
        sig_expected: bytes,
        valid: bool,
    ):
        dsa = ML_DSA(ParameterSet.ML_DSA_87)
        pk, sk = dsa.key_gen(seed)

        if pk_expected:
            self.assertEqual(bytes(pk), pk_expected)

        if not valid:
            with self.assertRaises(ValueError):
                dsa.sign(sk, msg, ctx, deterministic=True)
        else:
            sig = dsa.sign(sk, msg, ctx, deterministic=True)
            self.assertEqual(sig, sig_expected)
